-- Additional exam schema and 150-question seed
-- PostgreSQL schema and seed for pgAdmin
-- Contains 3 exams and 50 questions per major (150 total).

BEGIN;

CREATE TABLE IF NOT EXISTS exams (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  major VARCHAR(50) NOT NULL UNIQUE,
  title VARCHAR(255) NOT NULL,
  description TEXT,
  pass_score INTEGER NOT NULL DEFAULT 70 CHECK (pass_score BETWEEN 0 AND 100),
  accent_color VARCHAR(20) DEFAULT '#4f46e5',
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS exam_questions (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  exam_id BIGINT NOT NULL REFERENCES exams(id) ON DELETE CASCADE,
  created_by BIGINT,
  question_key VARCHAR(100) NOT NULL,
  question_text TEXT NOT NULL,
  options JSONB NOT NULL CHECK (jsonb_typeof(options) = 'array'),
  correct_answer INTEGER NOT NULL CHECK (correct_answer >= 0),
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT unique_exam_question_key UNIQUE (exam_id, question_key)
);

-- Compatibility with tables previously imported from the MariaDB dump.
-- Those tables used SMALLINT (0/1) for is_active and TEXT for options.
ALTER TABLE exams
  ALTER COLUMN is_active DROP DEFAULT;
ALTER TABLE exams
  ALTER COLUMN is_active TYPE BOOLEAN
  USING (LOWER(is_active::TEXT) IN ('1', 'true', 't'));
ALTER TABLE exams
  ALTER COLUMN is_active SET DEFAULT TRUE;

ALTER TABLE exam_questions
  ALTER COLUMN is_active DROP DEFAULT;
ALTER TABLE exam_questions
  ALTER COLUMN is_active TYPE BOOLEAN
  USING (LOWER(is_active::TEXT) IN ('1', 'true', 't'));
ALTER TABLE exam_questions
  ALTER COLUMN is_active SET DEFAULT TRUE;

ALTER TABLE exam_questions
  ALTER COLUMN options TYPE JSONB
  USING options::JSONB;

CREATE INDEX IF NOT EXISTS idx_exam_questions_exam_id ON exam_questions(exam_id);
CREATE INDEX IF NOT EXISTS idx_exam_questions_created_by ON exam_questions(created_by);

ON CONFLICT (major) DO UPDATE SET
  title = EXCLUDED.title,
  description = EXCLUDED.description,
  pass_score = EXCLUDED.pass_score,
  accent_color = EXCLUDED.accent_color,
  is_active = TRUE,
  updated_at = CURRENT_TIMESTAMP;

ON CONFLICT (exam_id, question_key) DO UPDATE SET
  question_text = EXCLUDED.question_text,
  options = EXCLUDED.options,
  correct_answer = EXCLUDED.correct_answer,
  sort_order = EXCLUDED.sort_order,
  is_active = TRUE,
  updated_at = CURRENT_TIMESTAMP;

COMMIT;

-- Verification query
SELECT e.major, COUNT(q.id) AS question_count
FROM exams e
LEFT JOIN exam_questions q ON q.exam_id = e.id AND q.is_active = TRUE
GROUP BY e.id, e.major
ORDER BY e.major;
